import kotlin.math.pow

fun power(a: Long, b: Long): Long {
    var ans = 1L
    var base = a
    var exp = b
    if (exp == 0L) return 1L
    while (exp > 0) {
        if (exp and 1L == 1L) ans *= base
        base *= base
        exp = exp shr 1
    }
    return ans
}

